package framework.view;
import adapter.presenter.ActivityPresenter;
import domain.entity.Activity;
import domain.entity.SortOption;
import domain.exception.EntityNotFoundException;
import domain.exception.ValidationException;
import framework.util.InputUtil;
import usecase.ActivityUseCase;
import java.util.List;
public class ActivityView {
    private final ActivityUseCase useCase; private final ActivityPresenter presenter; private final InputUtil input = new InputUtil(); private int lastId;
    public ActivityView(ActivityUseCase useCase, ActivityPresenter presenter) { this.useCase = useCase; this.presenter = presenter; }
    public void show() { boolean running = true; while (running) { presenter.dashboard(useCase.list()); menu(); String choice = input.readLine("Pilih : ").trim(); presenter.message(""); try { switch (choice.toLowerCase()) { case "1": add(); break; case "2": update(); break; case "3": search(); break; case "4": sort(); break; case "5": delete(); break; case "x": running = false; break; default: presenter.message("[!] Pilihan tidak dimengerti."); presenter.message(""); } } catch (ValidationException e) { presenter.message("[!] " + e.getMessage()); presenter.message(""); } catch (EntityNotFoundException e) { presenter.message("[!] Gagal menghapus kegiatan dengan ID: " + lastId + "."); presenter.message(""); } } }
    private void menu() { presenter.message("Menu:"); presenter.message("1. Tambah"); presenter.message("2. Ubah"); presenter.message("3. Cari"); presenter.message("4. Urutkan"); presenter.message("5. Hapus"); presenter.message("x. Keluar"); }
    private void add() throws ValidationException { presenter.message("[Menambah Kegiatan]"); String title = input.readLine("Judul (x Jika Batal) : "); if (title.trim().equalsIgnoreCase("x")) { presenter.message(""); return; } String day = input.readLine("Hari (x Jika Batal) : "); if (day.trim().equalsIgnoreCase("x")) { presenter.message(""); return; } String time = input.readLine("Waktu (x Jika Batal) : "); if (time.trim().equalsIgnoreCase("x")) { presenter.message(""); return; } presenter.added(useCase.add(title, day, time)); }
    private void update() throws ValidationException, EntityNotFoundException { presenter.message("[Mengubah Kegiatan]"); String id = input.readLine("ID Kegiatan yang diubah (x Jika Batal) : ").trim(); if (id.equalsIgnoreCase("x")) { presenter.message(""); return; } try { lastId = Integer.parseInt(id); } catch (NumberFormatException e) { presenter.message("[!] ID tidak valid!"); presenter.message(""); return; } String title = input.readLine("Judul Baru (Kosongkan jika tidak ingin mengubah) : "); String day = input.readLine("Hari Baru (Kosongkan jika tidak ingin mengubah) : "); String time = input.readLine("Waktu Baru (Kosongkan jika tidak ingin mengubah) : "); if (title.trim().equalsIgnoreCase("x")) { presenter.message(""); return; } if (day.matches("\\d{1,2}:\\d{2}") && time.trim().equalsIgnoreCase("x")) { time = day; day = ""; } else if (day.trim().equalsIgnoreCase("x") || time.trim().equalsIgnoreCase("x")) { presenter.message(""); return; } try { presenter.updated(useCase.update(lastId, title, day, time)); } catch (EntityNotFoundException e) { presenter.message("[!] Gagal mengubah kegiatan dengan ID: " + lastId + "."); presenter.message(""); } }
    private void search() throws ValidationException { presenter.message("[Mencari Kegiatan]"); String q = input.readLine("Kata Kunci (x Jika Batal) : "); if (q.trim().equalsIgnoreCase("x")) { presenter.message(""); return; } List<Activity> result = useCase.search(q); presenter.search(q, result); }
    private void sort() { presenter.message("[Mengurutkan Kegiatan]"); presenter.message("Pilihan Pengurutan:"); presenter.message("1. Hari (Senin -> Minggu)"); presenter.message("2. Waktu (Awal -> Akhir)"); presenter.message("3. Judul (A-Z)"); presenter.message("4. Judul (Z-A)"); presenter.message("x. Batal"); String value = input.readLine("Pilih : ").trim(); presenter.message(""); if (value.equalsIgnoreCase("x")) { presenter.message(""); return; } SortOption option; switch (value) { case "1": option = SortOption.DAY; break; case "2": option = SortOption.TIME; break; case "3": option = SortOption.TITLE_ASC; break; case "4": option = SortOption.TITLE_DESC; break; default: presenter.message("[!] Pilihan tidak valid!"); presenter.message(""); return; } presenter.sorted(useCase.sort(option)); }
    private void delete() throws EntityNotFoundException { presenter.message("[Menghapus Kegiatan]"); String value = input.readLine("[ID Kegiatan] yang dihapus (x Jika Batal) : ").trim(); if (value.equalsIgnoreCase("x")) { presenter.message(""); return; } try { lastId = Integer.parseInt(value); } catch (NumberFormatException e) { presenter.message("[!] ID tidak valid!"); presenter.message(""); return; } useCase.delete(lastId); presenter.deleted(); }
}